Let $[\delta_2, \mathscr{X}]$ and $y_i$ defined as previous, then 
\begin{enumerate} 
\item[(1)] $[\delta_2, \mathscr{X}] =
(\frac{\delta_2 X_1}{X_1}) \mathscr{X} - b_0 \delta_2$; 
\item[(2)] $\mathscr{X}y_j =
\delta_2\mathscr{X}y_{j-1} - (\frac{\delta_2 X_1}{X_1}) \mathscr{X}y_{j-1} +
b_0\,y_j$.
\end{enumerate}

We have
\begin{equation}  
\mathscr{X}y_j \sim
\sum_{i = 0}^{j-1}c_{i,j}\,b_i\,y_{j-i},\quad (j\geq 1)
\end{equation}
 where $c_{i,j}$ are positive integers, and $c_{0,j} = j$.

Let $\Lambda$ be a nontrivial expansion of $\mathscr{X}$, $A\in \Lambda$ with the lowest rank and $r =
\mathrm{ord}(\Lambda) $. Let $\mathbf{m}^*\in \mathcal{I}_A$ with the
highest degree and assume that $a_{\mathbf{m}^*} = 1$, then for any $\mathbf{m}\in \mathbb{Z}^{r+1}$, $\mathbf{m}<\mathbf{m}^*$, we have
\begin{equation}
 \mathscr{X}a_\mathbf{m} = (C({\mathbf{m}^*}) -
C({\mathbf{m}}))b_0a_{\mathbf{m}}
-\sum_{i=1}^{r-1}\sum_{j=i+1}^{r}(m_j+1)c_{i,j}b_ia_{{\Delta_{i,j}^{-1}}(\mathbf{m})}.
\end{equation}
Here $a_{\mathbf{m}} = 0$ whenever  $\mathbf{m}\not\in \mathcal{I}_A$.

In Lemma 15, for any $\mathbf{m}\leq \mathbf{m}^*$, let $k=\#(\mathbf{m})$ and $\mathcal{P}(\mathbf{m}) = \{\mathbf{p}_1,\cdots,
\mathbf{p}_k\}$, and assume $\Delta_{{i_l},{j_l}}(\mathbf{p}_l) = \mathbf{m},\
(l = 1,2,\cdots,k)$, then the coefficients $a_{\mathbf{p}_l},
a_{\mathbf{m}}$ satisfy
\begin{equation}
 \mathscr{X} a_{\mathbf{m}} = (C({\mathbf{m}^*}) -
C({\mathbf{m}}))b_0a_{\mathbf{m}} -\sum_{l = 1}^{\#(\mathbf{m})}
(m_{j_l}+1) c_{i_l,j_l} b_{i_l} a_{\mathbf{p}_l}.
\end{equation}

If there exists $a\in K$, $a\not=0$, such that
\begin{equation}
 \mathscr{X} a  = nb_0 a,
\end{equation}
where $n$ is non-zero integer, let 
\begin{equation}
A = (\delta_2y)^{|n|} - a^{|n|/n},
\end{equation}
then $\Lambda = \{X, A\}$ is a nontrivial expansion of $\mathscr{X}$.

If there exists $a\in K$ satisfying
\begin{equation}
 \mathscr{X} a = b_0 a  + b_1.
\end{equation}
Let
\begin{equation}
A = \delta_2^2y - a \delta_2y,
\end{equation}
then $\Lambda = \{X,A\}$ is a nontrivial expansion of $\mathscr{X}$.

If there exists $a\in K$ satisfying
\begin{equation} 

\mathscr{X} a = 2 b_0 a  + b_2.
\end{equation}
Let
\begin{equation}
A = 2 (\delta_2 y) (\delta_2^3 y) - 3 (\delta_2^2 y)^2 - a (\delta_2 y)^2,
\end{equation}
then $\Lambda = \{X,A\}$ is a nontrivial expansion of $\mathscr{X}$.

Let $A\in K\{y\}$, the differential ideal $\Lambda = \{A, X\}$ is a nontrivial expansion of $\mathscr{X}$ if, and only if, the equation
\begin{equation}

\left\{
\begin{array}{rcl}
\mathscr{X}y &=& 0\\
\mathscr{D}_Ay &=& 0
\end{array}\right.
\end{equation}
has a non constant solution in $\mathcal{A}(\Omega)$, with $\Omega$ an open subset of $\mathbb{C}^2$.
}

Consider following partial differential equations
\begin{equation}

\left\{
\begin{array}{rcl}
\dfrac{\partial u}{\partial x_1} &=& f(x_1,x_2,u)\\
\dfrac{\partial u}{\partial x_2} &=& g(x_1,x_2,u)
\end{array}
\right.
\end{equation}
Let
$$D_1 = \dfrac{\partial\ }{\partial x_1} + f(x_1,x_2,u)\dfrac{\partial\ }{\partial u},\quad D_2 = \dfrac{\partial\ }{\partial x_2} + g(x_1,x_2,u)\dfrac{\partial\ }{\partial u}.$$
If the functions $f$ and $g$ are analytic, and satisfy
\begin{equation}

D_2 f(x_1,x_2,u) \equiv D_1 g(x_1,x_2,u),
\end{equation}
in a neighborhood of $(0,0,0)$,  then the equation (69) has a unique solution $u = u(x_1,x_2)$ that is analytic on a neighborhood of $(0,0)$ and $u(0,0) = 0$.
}

Let the polynomial differential operator $\mathscr{X}$ given by (1), with coefficients $X_1,X_2\in K$,  then either
$0\leq \mathrm{ord}(\mathscr{X})\leq 3$, or $\mathrm{ord}(\mathscr{X}) = \infty$.
Furthermore, when $0\leq \mathrm{ord}(\mathscr{X})\leq 3$, we can always select an essential expansion $\Lambda$ of $\mathscr{X}$, such that $\Lambda = \{X, A\}$, with $A\in K\{y\}$ given below
\begin{enumerate}
\item[(1)] if $\mathrm{ord}(\mathscr{X}) = 0$, then
\begin{equation}

A =  y - a,\quad (a\in K\backslash\mathbb{R});
\end{equation}
\item[(2)] if $\mathrm{ord}(\mathscr{X}) = 1$, then
\begin{equation}

A=(\delta_2y)^n - a,\quad (n\in \mathbb{N}, a\in K);
\end{equation}
 \item[(3)] if $\mathrm{ord}(\mathscr{X})  = 2$, them
 \begin{equation}

A=\delta_2^2y - a \delta_2 y,\quad (a\in K);
 \end{equation}
\item[(4)] if $\mathrm{ord}(\mathscr{X}) = 3$, then
\begin{equation}

A= 2 (\delta_2 y) (\delta_2^3 y) - 3 (\delta_2^2 y)^2 - a (\delta_2 y)^2,\quad (a\in K).
\end{equation}
\end{enumerate}
